  TestValidator.equals(
    "active page 1 - current page",
    activePage1.pagination.current,
    1,
  );
  TestValidator.equals(
    "active page 1 - records total",
    activePage1.pagination.records,
    3,
  );
  TestValidator.equals(
    "active page 1 - pages total",
    activePage1.pagination.pages,
    2,
  );
